import{_ as a,o,c as r,ae as t}from"./chunks/framework.Dn6zxbF8.js";const u=JSON.parse('{"title":"Google Drive: hierarchy, audiences, and access","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/1917971986/references/google-drive.md","filePath":"adrs/1917971986/references/google-drive.md"}'),i={name:"adrs/1917971986/references/google-drive.md"};function n(s,e,l,d,c,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="google-drive-hierarchy-audiences-and-access" tabindex="-1">Google Drive: hierarchy, audiences, and access <a class="header-anchor" href="#google-drive-hierarchy-audiences-and-access" aria-label="Permalink to &quot;Google Drive: hierarchy, audiences, and access&quot;">​</a></h1><p>Verified against primary documentation on 2026-10-10.</p><h2 id="hierarchy" tabindex="-1">Hierarchy <a class="header-anchor" href="#hierarchy" aria-label="Permalink to &quot;Hierarchy&quot;">​</a></h2><p>A Google Workspace or Cloud Identity account is the top-level container for users, groups, configuration, and data, and corresponds to the notion of a tenant; it is identified by a domain name and is not itself a user account, but a directory of user accounts (<a href="https://docs.cloud.google.com/architecture/identity/overview-google-authentication" target="_blank" rel="noreferrer">Overview of Google identity management</a>). Under that account, organizational units (OUs) are sub-containers that segment user accounts into disjoint, hierarchical sets; each account has a root OU under which further OUs can be nested, and the customer&#39;s OU hierarchy is limited to 35 levels of depth (<a href="https://docs.cloud.google.com/architecture/identity/overview-google-authentication" target="_blank" rel="noreferrer">Overview of Google identity management</a>; <a href="https://developers.google.com/admin-sdk/directory/v1/guides/manage-org-units" target="_blank" rel="noreferrer">Admin SDK: Manage organizational units</a>). OUs hold policy, not work: they group people and devices, not Drive content.</p><p>Work itself lives in Drive, which has two kinds of containers. My Drive is personal storage where folders can nest up to 100 folders deep, including the parent folder, after which the 100th folder can hold files and shortcuts but no further folders. Shared drives are team-owned storage where a folder can likewise have up to 100 levels of nested folders, and a shared drive can hold up to 500,000 items total, including files, folders, shortcuts, and trashed items (<a href="https://support.google.com/a/answer/7338880?hl=en" target="_blank" rel="noreferrer">Shared drive limits</a>). This nesting-depth increase to 100 levels (up from 20) and the 500,000-item ceiling were announced in Google&#39;s July 2024 release notes (<a href="https://workspaceupdates.googleblog.com/2024/07/release-notes-07-12-2024.html" target="_blank" rel="noreferrer">Release notes, 07/12/2024</a>). Folders in Drive are freely nestable within these limits; there is no separate &quot;folder type&quot; distinct from a generic container.</p><p>A single Workspace customer account can also carry more than one domain name. An administrator can add a secondary domain so that a separate team or business unit gets its own domain for user addresses, all still managed from the same Admin console and the same customer account, alongside an alias domain option for users who only need an alternate address (<a href="https://knowledge.workspace.google.com/admin/domains/add-a-user-alias-domain-or-secondary-domain" target="_blank" rel="noreferrer">Add a user alias domain or secondary domain</a>). A secondary domain does not create a second customer account or a second hierarchy; it is a property of the one existing account.</p><h2 id="governance-and-work" tabindex="-1">Governance and work <a class="header-anchor" href="#governance-and-work" aria-label="Permalink to &quot;Governance and work&quot;">​</a></h2><p>Identity, billing, and policy settings live at the Workspace customer account and its organizational units, administered through the Admin console. Configuration groups, a separate mechanism from OUs, let administrators apply exceptions to specific users &quot;without changing your organizational structure,&quot; covering services including Drive, Calendar, Gmail, Meet, Vault, and Google Cloud Platform, plus administrative features such as context-aware access and data regions (<a href="https://knowledge.workspace.google.com/admin/users/advanced/customize-service-settings-using-configuration-groups" target="_blank" rel="noreferrer">Customize service settings using configuration groups</a>). A user&#39;s group settings generally override their OU&#39;s settings for these supported services, with one documented exception: a two-step verification (2SV) policy set on a child OU always takes precedence over a configuration group setting, regardless of group priority (<a href="https://knowledge.workspace.google.com/admin/users/advanced/customize-service-settings-using-configuration-groups" target="_blank" rel="noreferrer">Customize service settings using configuration groups</a>).</p><p>Work itself is held separately from this governance layer. In My Drive, the individual who created a file or folder owns it. In a shared drive, the team, not an individual, owns the content, so files persist when a member leaves (<a href="https://support.google.com/a/users/answer/7212025" target="_blank" rel="noreferrer">My Drive versus shared drives</a>).</p><h2 id="audiences-and-visibility" tabindex="-1">Audiences and visibility <a class="header-anchor" href="#audiences-and-visibility" aria-label="Permalink to &quot;Audiences and visibility&quot;">​</a></h2><p>For an individual Drive file or folder, general access can be set to Restricted (only people explicitly given access can open it), Anyone with the link (anyone on the internet with the link can access it without signing in), or a public option where anyone can search on Google and get access without signing in (<a href="https://support.google.com/drive/answer/2494822" target="_blank" rel="noreferrer">Share files from Google Drive</a>). Google Workspace also exposes target audiences, administrator-curated groups such as departments or teams that a user can choose as a sharing option alongside &quot;anyone in the organization&quot; or link sharing; target audiences are more restricted than organization-wide sharing because only the group&#39;s designated members gain access, and administrators create the audience, add its members, and apply it to specific organizational units in the Admin console before it appears as a sharing choice (<a href="https://knowledge.workspace.google.com/admin/groups/about-target-audiences" target="_blank" rel="noreferrer">About target audiences</a>).</p><p>Inside a shared drive, access is also split by capability through membership roles. Google documents five roles: Manager, who can manage members and upload, edit, move, or delete all files and folders and can delete the shared drive itself; Content manager, who can upload, edit, move, or delete files but cannot manage membership or move folders between drives; Contributor, who can edit files and add new ones but cannot move or delete existing files; Commenter, who can only comment; and Viewer, who can only view (<a href="https://support.google.com/a/users/answer/9310460?hl=en" target="_blank" rel="noreferrer">Shared drive roles and permissions</a>). These roles are a finer-grained, per-capability analogue to this ADR&#39;s discover, read, and change capabilities, applied to a single shared drive or to folders within it.</p><h2 id="narrowing-below-a-parent" tabindex="-1">Narrowing below a parent <a class="header-anchor" href="#narrowing-below-a-parent" aria-label="Permalink to &quot;Narrowing below a parent&quot;">​</a></h2><p>A child organizational unit can override an inherited setting: &quot;to keep a child organizational unit from inheriting its parent&#39;s settings, apply to the child any settings that are specific to it,&quot; and those custom settings remain unchanged even as the parent&#39;s setting changes elsewhere (<a href="https://knowledge.workspace.google.com/admin/users/advanced/how-the-organizational-structure-works" target="_blank" rel="noreferrer">How the organizational structure works</a>).</p><p>Within Drive content itself, shared drive managers and My Drive owners can restrict a folder to specific users through &quot;limited access,&quot; even though the surrounding shared drive or parent folder grants broader access. This folder-level restriction beta was announced in September 2024 (<a href="https://workspaceupdates.googleblog.com/2024/09/google-drive-beta-to-restrict-folder-access.html" target="_blank" rel="noreferrer">Google Drive: beta to restrict folder access</a>) and reached general availability, extended to both shared drives and My Drive, per a February 2025 update that also describes Google&#39;s plan to retire item-level restricted sharing in My Drive in favor of folder-level limited access by 2026 (<a href="https://workspaceupdates.googleblog.com/2025/02/updating-access-experience-in-google-drive.html" target="_blank" rel="noreferrer">Updating the access experience in Google Drive</a>).</p><h2 id="ceilings-from-above" tabindex="-1">Ceilings from above <a class="header-anchor" href="#ceilings-from-above" aria-label="Permalink to &quot;Ceilings from above&quot;">​</a></h2><p>Organization-wide policy can cap what any OU or user is allowed to do. External sharing controls illustrate this: an administrator can restrict users to sharing only with domains on an allowlist of trusted domains, up to 5,000 domains, and this allowlist governs sharing in Drive (files), Classroom (joining classes), Chat (conversations with people in trusted domains), and Looker Studio (asset access). An allowlisted domain must be Google Workspace and domain-verified, and allowlisting does not allow selecting a subset of behaviors per domain, all trusted domains are treated the same, and users still cannot share with personal (non-Workspace) accounts under this control (<a href="https://knowledge.workspace.google.com/admin/domains/allow-external-sharing-with-only-trusted-domains" target="_blank" rel="noreferrer">Allow external sharing with only trusted domains</a>). This is an administrator-configured ceiling, not a default-on restriction: Google Workspace ships with broader external sharing allowed until an administrator narrows it.</p><h2 id="discovery-versus-access" tabindex="-1">Discovery versus access <a class="header-anchor" href="#discovery-versus-access" aria-label="Permalink to &quot;Discovery versus access&quot;">​</a></h2><p>A limited-access folder is visible to people who otherwise have general access to the shared drive or parent folder, but they cannot open it: &quot;people with general access to the shared drive or shared folder can see the restricted folder in Drive, but will not be able to open it,&quot; and the folder appears grayed out to them (<a href="https://workspaceupdates.googleblog.com/2024/09/google-drive-beta-to-restrict-folder-access.html" target="_blank" rel="noreferrer">Google Drive: beta to restrict folder access</a>; <a href="https://workspaceupdates.googleblog.com/2025/02/updating-access-experience-in-google-drive.html" target="_blank" rel="noreferrer">Updating the access experience in Google Drive</a>). Those excluded users can request access directly from the folder view.</p><p>For an individual restricted file, a person who tries to open it without permission reaches a &quot;You need permission&quot; page where they can click &quot;Request access,&quot; optionally add an explanation, and send the request; the file&#39;s owner receives an email with the requester&#39;s name, email, and message, and the requester is notified by email if the request is approved or denied (<a href="https://support.google.com/drive/answer/53355?hl=en" target="_blank" rel="noreferrer">Fix file won&#39;t open</a>).</p><h2 id="small-customers" tabindex="-1">Small customers <a class="header-anchor" href="#small-customers" aria-label="Permalink to &quot;Small customers&quot;">​</a></h2><p>Not documented: Google&#39;s primary documentation describing organizational units and configuration groups is written from the perspective of an existing Workspace customer account and does not describe a distinct &quot;simplified&quot; mode that hides OUs for small customers. Separately, a personal (consumer) Google Account used with Drive sits entirely outside Workspace: it has no organizational unit, no Admin console, and no customer-level policy layer, and such a user only ever sees My Drive and individually owned files and folders, with the Restricted, link-sharing, and public general-access options available at the file level (<a href="https://support.google.com/drive/answer/2494822" target="_blank" rel="noreferrer">Share files from Google Drive</a>). Google&#39;s documentation does not state that a small Workspace customer&#39;s Admin console is hidden or simplified relative to a large one; it describes the same OU and configuration-group tools regardless of organization size.</p><h2 id="consolidation" tabindex="-1">Consolidation <a class="header-anchor" href="#consolidation" aria-label="Permalink to &quot;Consolidation&quot;">​</a></h2><p>Google Workspace Domain Transfer explicitly &quot;does not support merging user accounts or account deduplication,&quot; including in merger-and-acquisition scenarios involving duplicate accounts across two customer environments. Google states there is no tool that offers a comprehensive way to merge two Google Accounts covering all possible Google services; instead, administrators work service by service, migrating data such as Gmail, Drive, Calendar, and Contacts individually (through APIs, GAM, or a data migration service) rather than merging the underlying accounts or customer records themselves (<a href="https://knowledge.workspace.google.com/admin/domains/identity-merge-and-deduplication" target="_blank" rel="noreferrer">Identity merge and deduplication</a>). There is no documented administrator-facing operation that folds one Workspace customer account, with its Drive content, into another as a single step.</p><h2 id="relevance-to-this-adr" tabindex="-1">Relevance to this ADR <a class="header-anchor" href="#relevance-to-this-adr" aria-label="Permalink to &quot;Relevance to this ADR&quot;">​</a></h2><ul><li>Google&#39;s Workspace customer account lines up with this ADR&#39;s Organization: it is the tenant-level root holding identity, billing, and policy, confirmed directly by Google&#39;s own description of the account as &quot;the top-level container for users, groups, configuration, and data.&quot;</li><li>Google has no single node that plays the ADR&#39;s Workspace role. Organizational units carry policy and people, not work, while shared drives and My Drive hold work but sit entirely outside the OU tree; there is no &quot;direct child of the root that holds work&quot; in Google&#39;s model the way this ADR defines Workspace. Folders inside shared drives map more closely onto this ADR&#39;s Folder.</li><li>Configuration groups are a precedent for &quot;any level may widen or narrow&quot;: they let administrators grant exceptions to specific people without restructuring the hierarchy, similar in spirit to this ADR&#39;s grants and limits, though configuration groups attach to people and policy rather than to positions in a resource tree. Note the documented exception where a child OU&#39;s 2SV setting always wins over a configuration group, a precedence rule this ADR does not carry for its own grants and limits.</li><li>Limited-access folders are a direct, sourced example of this ADR&#39;s &quot;a limit may leave discovery open&quot; rule: excluded users see that the folder exists (grayed out) and can request access, exactly the discoverable-but-not-readable behavior the ADR cites Google Drive for.</li><li>Google&#39;s documented absence of an account-merge tool directly supports this ADR&#39;s claim that separately created organizations consolidate only through migration, not through an ordinary operation; Google&#39;s own wording that there is no comprehensive merge tool for all services matches the ADR&#39;s framing of consolidation as an explicit, costly step rather than a built-in capability.</li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><ul><li><a href="https://docs.cloud.google.com/architecture/identity/overview-google-authentication" target="_blank" rel="noreferrer">Overview of Google identity management</a></li><li><a href="https://developers.google.com/admin-sdk/directory/v1/guides/manage-org-units" target="_blank" rel="noreferrer">Admin SDK: Manage organizational units</a></li><li><a href="https://knowledge.workspace.google.com/admin/users/advanced/how-the-organizational-structure-works" target="_blank" rel="noreferrer">How the organizational structure works</a></li><li><a href="https://knowledge.workspace.google.com/admin/users/advanced/customize-service-settings-using-configuration-groups" target="_blank" rel="noreferrer">Customize service settings using configuration groups</a></li><li><a href="https://support.google.com/a/users/answer/7212025" target="_blank" rel="noreferrer">My Drive versus shared drives</a></li><li><a href="https://support.google.com/drive/answer/2494822" target="_blank" rel="noreferrer">Share files from Google Drive</a></li><li><a href="https://knowledge.workspace.google.com/admin/groups/about-target-audiences" target="_blank" rel="noreferrer">About target audiences</a></li><li><a href="https://support.google.com/a/users/answer/9310460?hl=en" target="_blank" rel="noreferrer">Shared drive roles and permissions</a></li><li><a href="https://knowledge.workspace.google.com/admin/domains/add-a-user-alias-domain-or-secondary-domain" target="_blank" rel="noreferrer">Add a user alias domain or secondary domain</a></li><li><a href="https://workspaceupdates.googleblog.com/2024/09/google-drive-beta-to-restrict-folder-access.html" target="_blank" rel="noreferrer">Google Drive: beta to restrict folder access</a></li><li><a href="https://workspaceupdates.googleblog.com/2025/02/updating-access-experience-in-google-drive.html" target="_blank" rel="noreferrer">Updating the access experience in Google Drive</a></li><li><a href="https://knowledge.workspace.google.com/admin/domains/allow-external-sharing-with-only-trusted-domains" target="_blank" rel="noreferrer">Allow external sharing with only trusted domains</a></li><li><a href="https://support.google.com/drive/answer/53355?hl=en" target="_blank" rel="noreferrer">Fix file won&#39;t open</a></li><li><a href="https://knowledge.workspace.google.com/admin/domains/identity-merge-and-deduplication" target="_blank" rel="noreferrer">Identity merge and deduplication</a></li><li><a href="https://support.google.com/a/answer/7338880?hl=en" target="_blank" rel="noreferrer">Shared drive limits</a></li><li><a href="https://workspaceupdates.googleblog.com/2024/07/release-notes-07-12-2024.html" target="_blank" rel="noreferrer">Release notes, 07/12/2024</a></li></ul>',28)])])}const p=a(i,[["render",n]]);export{u as __pageData,p as default};
